const cfg = { ...$json };
const zone = cfg.timezone || 'America/Los_Angeles';
const yesterday = $now.setZone(zone).minus({ days: 1 });
return [{
  json: {
    ...cfg,
    date_start: yesterday.toFormat('yyyy-MM-dd'),
    date_end: yesterday.toFormat('yyyy-MM-dd'),
    sync_label: yesterday.toFormat('yyyy-MM-dd'),
    updated_at: new Date().toISOString()
  }
}];

const cfg = $('Calculate Sync Dates').first().json;
const errors = [];
function nodeRows(name) {
  const items = $(name).all();
  const chunks = [];
  for (const item of items) {
    if (item.json?.error) {
      errors.push({ node: name, error: item.json.error.message || item.json.error });
      continue;
    }
    const payloads = Array.isArray(item.json) ? item.json : [item.json];
    chunks.push(...payloads);
  }
  return chunks.flatMap((chunk) => Array.isArray(chunk.results) ? chunk.results : []);
}
function num(value) {
  if (value === null || value === undefined || value === '') return 0;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}
function micros(value) { return num(value) / 1000000; }
function ratio(numerator, denominator) { return denominator > 0 ? numerator / denominator : null; }
function channelName(channelType) {
  const map = { SEARCH: 'Paid Search', DISPLAY: 'Display', PERFORMANCE_MAX: 'Performance Max', VIDEO: 'YouTube', SHOPPING: 'Shopping', DEMAND_GEN: 'Demand Gen', DISCOVERY: 'Discovery', LOCAL: 'Local', SMART: 'Smart' };
  return map[channelType] || channelType || 'Unknown';
}
function cleanText(value) {
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}
function firstTextAsset(values, index) {
  const item = Array.isArray(values) ? values[index] : null;
  return cleanText(item?.text || item?.assetText || item?.pinnedField || null);
}
function firstUrl(values) {
  return Array.isArray(values) && values[0] ? String(values[0]) : null;
}
function displayUrl(finalUrl, path1, path2) {
  if (!finalUrl) return null;
  try {
    const url = new URL(finalUrl);
    const paths = [path1, path2].filter(Boolean).join('/');
    const fallbackPath = url.pathname === '/' ? '' : url.pathname.replace(/\/$/, '');
    return url.hostname.replace(/^www\./, '') + (paths ? '/' + paths : fallbackPath);
  } catch {
    return finalUrl.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/$/, '');
  }
}
function metricBase(metrics) {
  const spend = micros(metrics.costMicros ?? metrics.cost_micros);
  const revenue = num(metrics.conversionsValue ?? metrics.conversions_value);
  const conversions = num(metrics.conversions);
  const clicks = num(metrics.clicks);
  const impressions = num(metrics.impressions);
  return { spend, revenue, conversions, store_visits: 0, clicks, impressions };
}
function addTotals(target, values) {
  target.spend += values.spend;
  target.revenue += values.revenue;
  target.conversions += values.conversions;
  target.store_visits += values.store_visits || 0;
  target.clicks += values.clicks;
  target.impressions += values.impressions;
}
function finalizeMetrics(row) {
  row.conversions = Math.round(row.conversions);
  row.store_visits = Number((row.store_visits || 0).toFixed(2));
  row.clicks = Math.round(row.clicks);
  row.impressions = Math.round(row.impressions);
  row.cpa = ratio(row.spend, row.conversions);
  row.roas = ratio(row.revenue, row.spend);
  row.ctr = ratio(row.clicks, row.impressions);
  row.cpc = ratio(row.spend, row.clicks);
  row.updated_at = cfg.updated_at;
  return row;
}
const emptyTotals = () => ({ spend: 0, revenue: 0, conversions: 0, store_visits: 0, clicks: 0, impressions: 0 });
const campaignRowsRaw = nodeRows('Google Ads searchStream - Campaign Daily');
const storeVisitRowsRaw = nodeRows('Google Ads searchStream - Store Visits Daily');
const adLifetimeRaw = nodeRows('Google Ads searchStream - Ad Lifetime');
const pmaxAssetRaw = nodeRows('Google Ads searchStream - PMax Asset Groups');
const pmaxAssetDetailsRaw = nodeRows('Google Ads searchStream - PMax Asset Group Assets');
const channelMap = new Map();
const campaignMap = new Map();
for (const result of campaignRowsRaw) {
  const campaign = result.campaign || {};
  const metrics = metricBase(result.metrics || {});
  const channel = channelName(campaign.advertisingChannelType || campaign.advertising_channel_type);
  const date = result.segments?.date || cfg.date_start;
  const channelKey = [date, 'Google Ads', channel].join('|');
  const channelRow = channelMap.get(channelKey) || { client_id: cfg.client_id, date, platform: 'Google Ads', channel, ...emptyTotals() };
  addTotals(channelRow, metrics);
  channelMap.set(channelKey, channelRow);
  const campaignId = String(campaign.id || '');
  if (!campaignId) continue;
  const campaignKey = [date, 'Google Ads', campaignId].join('|');
  const campaignRow = campaignMap.get(campaignKey) || { client_id: cfg.client_id, date, platform: 'Google Ads', channel, campaign_id: campaignId, campaign_name: campaign.name || null, wasted_spend: 0, ...emptyTotals() };
  addTotals(campaignRow, metrics);
  campaignMap.set(campaignKey, campaignRow);
}
function storeVisitCount(result) {
  const metrics = result.metrics || {};
  const direct = num(metrics.allConversionsFromStoreVisit ?? metrics.all_conversions_from_store_visit);
  const locationAsset = num(metrics.allConversionsFromLocationAssetStoreVisits ?? metrics.all_conversions_from_location_asset_store_visits);
  return direct > 0 ? direct : locationAsset;
}
for (const result of storeVisitRowsRaw) {
  const visits = storeVisitCount(result);
  if (visits <= 0) continue;
  const campaign = result.campaign || {};
  const channel = channelName(campaign.advertisingChannelType || campaign.advertising_channel_type);
  const date = result.segments?.date || cfg.date_start;
  const channelKey = [date, 'Google Ads', channel].join('|');
  const channelRow = channelMap.get(channelKey) || { client_id: cfg.client_id, date, platform: 'Google Ads', channel, ...emptyTotals() };
  channelRow.store_visits += visits;
  channelMap.set(channelKey, channelRow);
  const campaignId = String(campaign.id || '');
  if (!campaignId) continue;
  const campaignKey = [date, 'Google Ads', campaignId].join('|');
  const campaignRow = campaignMap.get(campaignKey) || { client_id: cfg.client_id, date, platform: 'Google Ads', channel, campaign_id: campaignId, campaign_name: campaign.name || null, wasted_spend: 0, ...emptyTotals() };
  campaignRow.store_visits += visits;
  campaignMap.set(campaignKey, campaignRow);
}
const daily_performance = [...channelMap.values()].map(finalizeMetrics);
const campaign_daily_performance = [...campaignMap.values()].map(finalizeMetrics);
function creativeFromAd(result) {
  const ad = result.adGroupAd?.ad || result.ad_group_ad?.ad || {};
  const rsa = ad.responsiveSearchAd || ad.responsive_search_ad || {};
  const eta = ad.expandedTextAd || ad.expanded_text_ad || {};
  const finalUrl = firstUrl(ad.finalUrls || ad.final_urls);
  const headline = firstTextAsset(rsa.headlines, 0) || cleanText(eta.headlinePart1 || eta.headline_part1) || cleanText(ad.name);
  const headline2 = firstTextAsset(rsa.headlines, 1) || cleanText(eta.headlinePart2 || eta.headline_part2);
  const headline3 = firstTextAsset(rsa.headlines, 2);
  const description = firstTextAsset(rsa.descriptions, 0) || cleanText(eta.description);
  const description2 = firstTextAsset(rsa.descriptions, 1);
  const path1 = cleanText(rsa.path1);
  const path2 = cleanText(rsa.path2);
  return {
    ad_type: ad.type || null,
    status: result.adGroupAd?.status || result.ad_group_ad?.status || null,
    headline,
    headline_2: headline2,
    headline_3: headline3,
    description,
    description_2: description2,
    final_url: finalUrl,
    display_url: displayUrl(finalUrl, path1, path2),
    preview_url: null,
    image_url: null,
    thumbnail_url: null
  };
}
function normalizeAd(result, lifetime = false) {
  const campaign = result.campaign || {};
  const adGroup = result.adGroup || result.ad_group || {};
  const ad = result.adGroupAd?.ad || result.ad_group_ad?.ad || {};
  const metrics = metricBase(result.metrics || {});
  const adId = String(ad.id || '');
  if (!adId) return null;
  const channel = channelName(campaign.advertisingChannelType || campaign.advertising_channel_type);
  const creative = creativeFromAd(result);
  const row = {
    client_id: cfg.client_id,
    platform: 'Google Ads',
    channel,
    campaign_id: campaign.id ? String(campaign.id) : null,
    campaign_name: campaign.name || null,
    ad_group_id: adGroup.id ? String(adGroup.id) : null,
    ad_group_name: adGroup.name || null,
    ad_id: adId,
    ad_name: cleanText(ad.name) || creative.headline || creative.display_url,
    creative_id: adId,
    creative_name: cleanText(ad.name) || creative.headline,
    creative_preview_url: creative.preview_url,
    ...creative,
    ...metrics,
    source_updated_at: cfg.updated_at,
    raw_payload: result
  };
  if (!lifetime) row.date = result.segments?.date || cfg.date_start;
  if (lifetime) row.date_range = 'ALL_TIME';
  return finalizeMetrics(row);
}
function normalizePmaxAssetGroup(result) {
  const campaign = result.campaign || {};
  const assetGroup = result.assetGroup || result.asset_group || {};
  const metrics = metricBase(result.metrics || {});
  const detail = pmaxAssetDetails.get(pmaxAssetGroupKey(result)) || { headlines: [], descriptions: [], image_url: null, thumbnail_url: null, raw_assets: [] };
  const assetGroupId = assetGroup.id ? String(assetGroup.id) : null;
  if (!assetGroupId) return null;
  const finalUrl = firstUrl(assetGroup.finalUrls || assetGroup.final_urls);
  const row = {
    client_id: cfg.client_id,
    platform: 'Google Ads',
    channel: 'Performance Max',
    campaign_id: campaign.id ? String(campaign.id) : null,
    campaign_name: campaign.name || null,
    ad_group_id: assetGroupId,
    ad_group_name: assetGroup.name || null,
    ad_id: 'asset_group:' + assetGroupId,
    ad_name: assetGroup.name || 'Performance Max asset group',
    ad_type: 'ASSET_GROUP',
    status: assetGroup.status || null,
    headline: detail.headlines[0] || assetGroup.name || 'Performance Max asset group',
    headline_2: detail.headlines[1] || null,
    headline_3: detail.headlines[2] || null,
    description: detail.descriptions[0] || null,
    description_2: detail.descriptions[1] || null,
    final_url: finalUrl,
    display_url: displayUrl(finalUrl, null, null),
    preview_url: null,
    image_url: detail.image_url || null,
    thumbnail_url: detail.thumbnail_url || null,
    creative_id: assetGroupId,
    creative_name: assetGroup.name || null,
    creative_preview_url: null,
    date_range: 'ALL_TIME',
    source_updated_at: cfg.updated_at,
    raw_payload: { asset_group: result, assets: detail.raw_assets },
    ...metrics
  };
  return finalizeMetrics(row);
}
function aggregateLifetime(rows) {
  const map = new Map();
  for (const row of rows.filter(Boolean)) {
    const key = [row.client_id, row.platform, row.campaign_id || '', row.ad_id].join('|');
    const current = map.get(key);
    if (!current) {
      map.set(key, { ...row });
      continue;
    }
    addTotals(current, row);
    for (const field of ['ad_name','ad_type','status','headline','headline_2','headline_3','description','description_2','display_url','final_url','preview_url','image_url','thumbnail_url','creative_name','creative_preview_url']) {
      if (!current[field] && row[field]) current[field] = row[field];
    }
  }
  return [...map.values()].map(finalizeMetrics);
}
function nestedValue(obj, path) {
  return path.split('.').reduce((current, key) => current?.[key], obj);
}
function pmaxAssetGroupKey(result) {
  const campaign = result.campaign || {};
  const assetGroup = result.assetGroup || result.asset_group || {};
  return [campaign.id || '', assetGroup.id || ''].join('|');
}
function buildPmaxAssetDetails(results) {
  const map = new Map();
  for (const result of results) {
    const key = pmaxAssetGroupKey(result);
    if (key === '|') continue;
    const detail = map.get(key) || { headlines: [], descriptions: [], image_url: null, thumbnail_url: null, raw_assets: [] };
    const fieldType = String(result.assetGroupAsset?.fieldType || result.asset_group_asset?.field_type || '').toUpperCase();
    const asset = result.asset || {};
    const text = cleanText(asset.textAsset?.text || asset.text_asset?.text);
    const imageUrl = cleanText(asset.imageAsset?.fullSize?.url || asset.image_asset?.full_size?.url || nestedValue(asset, 'imageAsset.full_size.url') || nestedValue(asset, 'image_asset.fullSize.url'));
    if (text) {
      if (fieldType.includes('DESCRIPTION')) detail.descriptions.push(text);
      else detail.headlines.push(text);
    }
    if (imageUrl && !detail.image_url) {
      detail.image_url = imageUrl;
      detail.thumbnail_url = imageUrl;
    }
    detail.raw_assets.push(result);
    map.set(key, detail);
  }
  return map;
}
const pmaxAssetDetails = buildPmaxAssetDetails(pmaxAssetDetailsRaw);
const lifetimeRows = [
  ...adLifetimeRaw.map((result) => normalizeAd(result, true)),
  ...pmaxAssetRaw.map(normalizePmaxAssetGroup)
];
const ad_lifetime_performance = aggregateLifetime(lifetimeRows);
return [{ json: { client_id: cfg.client_id, client_name: cfg.client_name, date_start: cfg.date_start, date_end: cfg.date_end, errors, daily_performance, campaign_daily_performance, ad_lifetime_performance, counts: { daily_performance: daily_performance.length, campaign_daily_performance: campaign_daily_performance.length, ad_lifetime_performance: ad_lifetime_performance.length } } }];

const data = $('Normalize Paid Ads Performance').first().json;
const errors = [...(data.errors || [])];
for (const node of ['Supabase Upsert - daily_performance', 'Supabase Upsert - campaign_daily_performance', 'Supabase Upsert - ad_lifetime_performance']) {
  for (const item of $(node).all()) {
    if (item.json?.error) errors.push({ node, error: item.json.error.message || item.json.error });
  }
}
const ok = errors.length === 0;
return [{ json: { ...data, ok, errors, message: ok
  ? 'Portal paid ads sync succeeded for ' + data.client_name + '.\nDate: ' + data.date_start + '\nRows: daily_performance=' + data.counts.daily_performance + ', campaign_daily_performance=' + data.counts.campaign_daily_performance + ', ad_lifetime_performance=' + data.counts.ad_lifetime_performance + '\nStore visits are pulled from Google Ads dedicated store-visit metrics.'
  : 'Portal paid ads sync failed for ' + data.client_name + '.\nDate: ' + data.date_start + '\nReview the failed n8n execution.\nErrors: ' + JSON.stringify(errors)
} }];

parameters.jsonBody:
={{
{
  query: "SELECT
    segments.date,
    campaign.id,
    campaign.name,
    campaign.status,
    campaign.advertising_channel_type,
    metrics.all_conversions_from_store_visit,
    metrics.all_conversions_from_location_asset_store_visits
  FROM campaign
  WHERE segments.date DURING YESTERDAY
    AND campaign.status != 'REMOVED'
    AND campaign.advertising_channel_type IN ('SEARCH', 'DISPLAY', 'PERFORMANCE_MAX')"
}
}}
